/**
 * Other spellings of curated shades (lower-case key → canonical name).
 * Word-level spellings ("grey" → "gray", "colour" → "color") are handled by the
 * normaliser, so they are not repeated here.
 */
export const COLOR_ALIASES: Record<string, string> = {
    "charcoal gray": "Charcoal",
    "navy blue": "Navy",
    "off-white": "Off White",
    "olive green": "Olive",
    "midnight blue": "Midnight",
    "sage green": "Sage",
    "mint green": "Mint",
    clear: "Transparent",
    "multi-color": "Multicolor",
    "multi color": "Multicolor",
    "multi-colored": "Multicolor",
    multicolored: "Multicolor",
};

const COLOR_OPTION_BY_NAME = new Map(COLOR_OPTIONS.map((c) => [c.name.toLowerCase(), c]));

/** Curated shade by name (case-insensitive, no alias resolution) */
export function getCuratedShade(name: string): ColorShade | undefined {
    return COLOR_OPTION_BY_NAME.get(name.toLowerCase());
}

/**
 * Color options that use images instead of hex codes.
 * These represent multiple colors or patterns that can't be shown as a single color swatch.
 * Using PNG format for better storefront compatibility (SVGs may not render in swatches).
 */
export const IMAGE_COLOR_OPTIONS: Array<{ name: string; imagePath: string }> = [
    { name: "Multicolor", imagePath: "color-images/multicolor.png" },
    { name: "Multi-Color", imagePath: "color-images/multicolor.png" },
    { name: "Rainbow", imagePath: "color-images/rainbow.png" },
    { name: "Assorted", imagePath: "color-images/assorted.png" },
    { name: "Mixed", imagePath: "color-images/assorted.png" },
    { name: "Patterned", imagePath: "color-images/patterned.png" },
    { name: "Printed", imagePath: "color-images/patterned.png" },
    { name: "Gradient", imagePath: "color-images/gradient.png" },
];

/**
 * Check if a color option uses an image instead of a hex code
 */
export function colorHasImage(colorName: string): boolean {
    return IMAGE_COLOR_OPTIONS.some((c) => c.name.toLowerCase() === colorName.toLowerCase());
}

/**
 * Get the image path for a color option (if it uses an image)
 */
export function getColorImagePath(colorName: string): string | undefined {
    const imageColor = IMAGE_COLOR_OPTIONS.find(
        (c) => c.name.toLowerCase() === colorName.toLowerCase()
    );
    return imageColor?.imagePath;
}

/**
 * Universal property groups - only properties that apply across ALL store types
 *
 * Currently only Color is universal because:
 * 1. Color is relevant for products in any domain (beauty, fashion, furniture, electronics, etc.)
 * 2. Color requires hex codes for proper Shopware display
 * 3. The AI can reuse these predefined colors with correct hex values
 *
 * All other properties are domain-specific and should be AI-generated:
 * - Beauty: Volume, Scent, Skin Type, Hair Type
 * - Fashion: Size, Fabric, Fit, Length
 * - Furniture: Material, Dimensions, Style
 * - Electronics: Storage, Screen Size, Connectivity
 */
export const UNIVERSAL_PROPERTY_GROUPS: CachedPropertyGroup[] = [
    {
        name: "Color",
        slug: "color",
        displayType: "color",
        options: COLOR_OPTIONS.map((c) => c.name),
        colorHexCodes: Object.fromEntries(COLOR_OPTIONS.map((c) => [c.name, c.hex])),
        createdAt: "2025-01-01T00:00:00.000Z",
        source: "fixture",
    },
];

/**
 * Color hex lookup map for quick access
 */
export const COLOR_HEX_MAP: Record<string, string> = Object.fromEntries(
    COLOR_OPTIONS.map((c) => [c.name.toLowerCase(), c.hex])
);

/**
 * Get hex code for a color name (case-insensitive)
 */
export function getColorHexCode(colorName: string): string | undefined {
    return COLOR_HEX_MAP[colorName.toLowerCase()];
}

/**
 * Get all universal property groups
 */
export function getUniversalPropertyGroups(): CachedPropertyGroup[] {
    return UNIVERSAL_PROPERTY_GROUPS;
}
